// Keep places not already in the sheet, score them and explain the score.
const settings = $('Settings').first().json;
const hotScore = Number(settings.hotScore) || 50;
const warmScore = Number(settings.warmScore) || 30;
const known = new Set($('Read saved leads').all().map((i) => String(i.json.placeId ?? '')).filter(Boolean));
const today = new Date().toISOString().slice(0, 10);

// Each rule: [applies?, points, reason, sales angle]. Adapt the weights to what you sell.
const rules = (p) => [
  [!p.website, 35, 'No website', 'Offer a simple website'],
  [p.isClaimed === false, 20, 'Unclaimed Google profile', 'Offer to claim and complete the Google profile'],
  [p.rating != null && p.rating < 4 && p.reviewsCount >= 5, 15, `Rating ${p.rating} on ${p.reviewsCount} reviews`, 'Offer review management'],
  [p.reviewsCount != null && p.reviewsCount < 15, 10, `Only ${p.reviewsCount} reviews`, 'Offer a review campaign'],
  [!p.openingHours, 5, 'No opening hours', 'Offer to claim and complete the Google profile'],
  [!!p.phone, 15, 'Phone listed', null],
];

const seen = new Set();
const leads = [];
for (const { json: p } of $('Run Google Maps Businesses').all()) {
  if (p.found === false || !p.placeId || known.has(p.placeId) || seen.has(p.placeId)) continue;
  seen.add(p.placeId);
  const hits = rules(p).filter(([applies]) => applies);
  const score = Math.min(100, hits.reduce((sum, [, points]) => sum + points, 0));
  const angles = [...new Set(hits.map(([, , , angle]) => angle).filter(Boolean))];
  leads.push({
    json: {
      placeId: p.placeId,
      name: p.name,
      leadScore: score,
      tier: score >= hotScore ? 'hot' : score >= warmScore ? 'warm' : 'cold',
      reasons: hits.map(([, , reason]) => reason).join('; '),
      salesAngle: angles.join('; '),
      category: p.category,
      phone: p.phone,
      website: p.website,
      rating: p.rating,
      reviewsCount: p.reviewsCount,
      isClaimed: p.isClaimed,
      address: p.address,
      city: p.city,
      googleMapsUrl: p.googleMapsUrl,
      searchQuery: p.searchQuery,
      dateAdded: today,
    },
  });
}
return leads.sort((a, b) => b.json.leadScore - a.json.leadScore);

// One Slack message with this run's hot leads (best first). No hot lead: no message.
const hot = $input.all().map((i) => i.json).filter((l) => l.tier === 'hot');
if (hot.length === 0) return [];
const shown = hot.slice(0, 15).map((l) =>
  `• *${l.name}* (${l.category ?? 'business'}, ${l.city ?? ''}) score ${l.leadScore}\n` +
  `   ${l.reasons}\n   :bulb: ${l.salesAngle || '-'}\n` +
  `   ${l.phone ?? 'no phone'} | <${l.googleMapsUrl}|Google Maps>`);
const more = hot.length > shown.length ? `\n…and ${hot.length - shown.length} more in the sheet.` : '';
return [{ json: { text: `:dart: *${hot.length} new hot lead${hot.length > 1 ? 's' : ''}* from Google Maps\n\n${shown.join('\n\n')}${more}`, hotLeads: hot.length } }];
